/* Atlas IA v0.1: local retrieval, no remote model or conversation storage. */
(()=>{
'use strict';
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const help=[
 {keys:['baixar','download','csv','excel','xlsx'],title:'Como baixar dados',text:'Nos painéis Brasil, Internacional, Comércio exterior e Municípios, ajuste os filtros e use “Baixar recorte CSV”. Em “Buscar bases abertas”, os itens identificados como “CSV no Atlas” têm arquivos preparados. Outros itens levam ao repositório original. Para abrir CSV no Excel, use a importação de Texto/CSV e confira o separador e as casas decimais. Esta versão não converte arquivos para XLSX.',scope:'catalog'},
 {keys:['aquicultura','cultivo','extrativa','diferenca'],title:'Aquicultura e pesca extrativa',text:'Aquicultura é o cultivo de organismos aquáticos com intervenção no processo de produção. Pesca extrativa é a captura de organismos em ambientes naturais. No Atlas, essas séries são separadas: na aba Brasil, escolha Aquicultura ou Captura. Não some bases com cobertura sobreposta.',scope:'national'},
 {keys:['ncm','fob','exportacao','importacao','comercio'],title:'Comércio exterior: cobertura e medidas',text:'NCM é a classificação dos produtos comercializados. O painel usa o capítulo 03: seu recorte não inclui todas as conservas, óleos e farinhas de pescado. Valor FOB está em dólares e peso líquido em quilogramas na base. Valor dividido por peso é um valor unitário médio, não um preço de varejo. O ano de 2026 está parcial na cópia do Atlas.',scope:'trade'},
 {keys:['grafico','queda','diminuiu','aumentou','interpretar'],title:'Como interpretar o gráfico',text:'Confira o título, a unidade, os filtros e o período antes de comparar. Uma queda pode refletir mudança de cobertura ou período incompleto. O gráfico sozinho não demonstra a causa da variação. Esta versão explica a leitura, mas ainda não calcula respostas a partir dos pontos do gráfico.',scope:'method'},
 {keys:['ausente','zero','suprimido','traco'],title:'Ausências não são zero',text:'O traço (—) indica ausência de observação comparável. Dados ausentes, suprimidos ou não aplicáveis não são convertidos em zero. Percentuais de variação dependem de valores disponíveis nos dois períodos.',scope:'method'},
 {keys:['tonelada','peso vivo','unidade','quilograma'],title:'Unidades e comparabilidade',text:'Uma tonelada equivale a 1.000 kg. As séries FAO do Atlas usam toneladas de peso vivo; o comércio usa peso líquido do produto. Essas medidas não são diretamente equivalentes. No IBGE, o Atlas converteu kg para toneladas e mil reais para R$ milhões. Valores monetários são nominais.',scope:'method'},
 {keys:['licenca','comercial','permissao','reutilizar','citar','fonte'],title:'Fontes e reutilização',text:'Cada ficha do catálogo mostra a instituição, a licença declarada e o link de evidência. Consulte as condições na fonte antes de reutilizar. Cite o conjunto original, seu recorte, as transformações e a data de acesso. O rótulo “dados abertos” sozinho não substitui a licença.',scope:'catalog'},
 {keys:['rstudio','codigo','python','script'],title:'Levar os dados ao RStudio',text:'Baixe primeiro um CSV e confira seu separador, unidades e colunas. No RStudio, um ponto de partida é: dados <- read.csv(file.choose(), check.names = FALSE). Se o arquivo separar colunas com ponto e vírgula e usar vírgula decimal, use read.csv2. Esta versão ainda não executa R nem gera análises automaticamente.',scope:'catalog'},
 {keys:['usar','funciona','ajuda','ola','oi'],title:'Seu guia no Atlas',text:'Use Brasil para séries nacionais, Internacional para FAO, Comércio exterior para exportações/importações e Municípios para o recorte municipal. Em Buscar bases abertas, filtre área, subtema, cobertura e tipo de acesso. Posso localizar conjuntos e explicar conceitos. Respondo por busca em conteúdo preparado; ainda não há um modelo generativo conectado.',scope:'catalog'}
];
const stop=new Set('quero dados dado base bases sobre para como onde uma um de da do das dos no na nos nas o a os as e em por que qual quais encontrar encontre buscar me mostre tem ha preciso saber'.split(' '));
const aliases={exportacao:'comercio',exportacoes:'comercio',importacao:'comercio',importacoes:'comercio',cultivo:'aquicultura',peixe:'pesca',peixes:'pesca',brasileira:'brasil',brasileiro:'brasil'};
function search(items,q){const terms=[...new Set(norm(q).split(/[^a-z0-9]+/).filter(t=>t.length>1&&!stop.has(t)).map(t=>aliases[t]||t))];if(!terms.length)return[];return items.map(x=>{const title=norm(x.title),body=norm([x.title,x.area,x.topic,x.publisher,x.description,x.scale,...(x.tags||[])].join(' '));const hits=terms.filter(t=>body.includes(t));return {x,score:hits.length/terms.length*10+hits.filter(t=>title.includes(t)).length+(x.access==='prepared'?0.5:0),hits:hits.length};}).filter(r=>r.hits>0).sort((a,b)=>b.score-a.score).slice(0,4).map(r=>r.x)}
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e};
function go(scope){document.querySelector('.scope-tabs [data-scope="'+scope+'"]').click();close()}
const launch=node('button','Atlas IA · Ajuda','ai-launch');launch.type='button';launch.setAttribute('aria-expanded','false');launch.setAttribute('aria-controls','atlas-assistant');document.body.append(launch);
const panel=node('section',null,'ai-panel');panel.id='atlas-assistant';panel.hidden=true;panel.setAttribute('aria-label','Atlas IA — assistente do site');
const head=node('div',null,'ai-head');head.append(node('strong','Atlas IA'),node('span','Guia gratuito · versão 0.1'));
const closeBtn=node('button','Fechar');closeBtn.type='button';head.append(closeBtn);panel.append(head);
panel.append(node('p','Busca no catálogo e explicações preparadas. Sem IA generativa conectada.','ai-notice'));
const log=node('div',null,'ai-log');log.setAttribute('role','log');log.setAttribute('aria-live','polite');log.setAttribute('aria-relevant','additions');panel.append(log);
const suggestions=node('div',null,'ai-suggestions');for(const q of ['Como baixar CSV?','Dados de aquicultura brasileira','O que é NCM?','Explique este gráfico']){const b=node('button',q);b.type='button';b.onclick=()=>ask(q);suggestions.append(b)}panel.append(suggestions);
const form=node('form',null,'ai-form'),label=node('label','Sua pergunta');label.htmlFor='ai-question';const input=node('input');input.id='ai-question';input.placeholder='Pergunte sobre o Atlas…';input.maxLength=500;input.autocomplete='off';input.required=true;const send=node('button','Enviar');send.type='submit';form.append(label,input,send);panel.append(form);
const clear=node('button','Limpar conversa','ai-clear');clear.type='button';clear.onclick=()=>{log.replaceChildren();welcome()};panel.append(clear);document.body.append(panel);
function message(text,user=false){const e=node('article',null,user?'ai-message ai-user':'ai-message');e.append(node('strong',user?'Você':'Atlas IA'),node('p',text));log.append(e);log.scrollTop=log.scrollHeight;return e}
function welcome(){message('Olá! Posso ajudar a usar o Atlas, entender indicadores e encontrar conjuntos no catálogo. As perguntas ficam apenas nesta página e não são enviadas a serviços de IA. Para começar, escolha um atalho ou escreva sua pergunta.')}
function close(){panel.hidden=true;launch.setAttribute('aria-expanded','false');launch.focus()}
launch.onclick=()=>{panel.hidden=!panel.hidden;launch.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)input.focus()};closeBtn.onclick=close;panel.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
let cache,busy=false;async function catalog(){if(cache)return cache;const r=await fetch('catalog.json');if(!r.ok)throw Error('catalog');const data=await r.json();if(!Array.isArray(data.items))throw Error('schema');cache=data;return data}
function link(label,url){try{const u=new URL(url,location.href);if(!['http:','https:'].includes(u.protocol))return node('span',label);const a=node('a',label);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';return a}catch{return node('span',label)}}
async function ask(q){q=q.trim();if(!q||busy)return;busy=true;send.disabled=true;input.value='';message(q,true);const n=norm(q);const wantsData=/\b(dados|bases?|dataset|encontr|busc|procuro)/.test(n)&&!/(baix|download|licenca|citar|fonte)/.test(n);const quantitative=/(quanto|quantos|qual estado|qual pais|produziu mais|maior produtor|total de|calcule)/.test(n);const h=help.map(x=>({x,s:x.keys.filter(k=>n.includes(k)).length})).sort((a,b)=>b.s-a.s)[0];
try{
if(quantitative){message('Ainda não consulto nem calculo valores nas tabelas. Posso indicar conjuntos relacionados para você verificar o período e aplicar os filtros no painel. Não vou estimar um número sem consultar os registros.')}
if(h.s&&!wantsData&&!quantitative){const e=message(h.x.text);e.append(node('small','Base da resposta: guia e metodologia do Atlas.'));const b=node('button','Abrir '+({catalog:'catálogo',national:'Brasil',trade:'Comércio exterior',method:'Metodologia'}[h.x.scope]));b.type='button';b.onclick=()=>go(h.x.scope);e.append(b)}
else {const data=await catalog(),found=search(data.items,q);const e=message(found.length?'Estas são correspondências de texto no catálogo. Confira a ficha: encontrar uma base não garante que ela contenha a espécie, o local ou o período solicitado.':'Não encontrei uma correspondência no catálogo. Tente uma instituição (IBGE, FAO, MDIC), espécie ou tema, como aquicultura. Para ajuda, pergunte “Como baixar CSV?”.');for(const x of found){const card=node('div',null,'ai-result');card.append(node('strong',x.title),node('p',x.description),node('small',`${x.publisher} · ${x.access==='research'?'Publicação':'Cobertura'}: ${x.coverage||x.year||'ver fonte'}`),node('small','Licença declarada no catálogo: '+(x.license||'consultar fonte')),link('Consultar fonte',x.source));if(x.file)card.append(link(x.access==='prepared'?'Baixar CSV do Atlas':'Abrir arquivo na fonte',x.file));e.append(card)}e.append(node('small','Catálogo conferido em '+data.checked+'. Não é uma pesquisa na internet em tempo real.'))}
}catch{message('Não consegui carregar o catálogo. Verifique sua conexão e envie a pergunta novamente. As explicações de uso continuam disponíveis pelos atalhos.')}
finally{busy=false;send.disabled=false;log.scrollTop=log.scrollHeight;input.focus()}}
form.onsubmit=e=>{e.preventDefault();ask(input.value)};welcome();
// Pure retrieval hook for regression verification; no data mutation.
window.AtlasAssistant={search};
})();
